                int leftVal = dp[j][0], leftCuts = dp[j][1];
                int rightVal = dp[i - j][0], rightCuts = dp[i - j][1];
​
                int prod = leftVal * rightVal;
                int cuts = leftCuts + rightCuts + 1;
