function solve(X) {
    const dp = Array.from({ length: X + 1 }, () => [0, 0]); // dp[i] = [最大收益, 最小切割次数]
    const path = Array(X + 1).fill(0); // path[i] = 第一次切的位置，0表示不切
​
    for (let i = 1; i <= X; i++) {
        let maxVal = i;
        let minCuts = 0;
        let cutPos = 0;
​
        for (let j = 1; j < i; j++) {
            const [leftVal, leftCuts] = dp[j];
            const [rightVal, rightCuts] = dp[i - j];
            const prod = leftVal * rightVal;
            const cuts = leftCuts + rightCuts + 1;
​
            if (prod > maxVal || (prod === maxVal && cuts < minCuts)) {
                maxVal = prod;
                minCuts = cuts;
                cutPos = j;
            }
        }
​
        dp[i] = [maxVal, minCuts];
        path[i] = cutPos;
    }
​
    // 回溯方案
    const res = [];
    function backtrack(n) {
        if (path[n] === 0) {
            res.push(n);
        } else {
            backtrack(path[n]);
            backtrack(n - path[n]);
        }
    }
​
    backtrack(X);
    res.sort((a, b) => a - b);
    console.log(res.join(' '));
}
