package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
)
​
func backtrack(n int, path []int, res *[]int) {
    if path[n] == 0 {
        *res = append(*res, n)
    } else {
        backtrack(path[n], path, res)
        backtrack(n - path[n], path, res)
    }
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    X, _ := strconv.Atoi(line[:len(line)-1])
​
    type State struct {
        value int
        cuts  int
    }
​
    dp := make([]State, X+1)   // dp[i] = State{最大收益, 最小切割次数}
    path := make([]int, X+1)   // path[i] 表示切割第一刀的位置，0 表示不切
​
    for i := 1; i <= X; i++ {
        maxVal := i       // 不切割的收益
        minCuts := 0
        cutPos := 0
​
        for j := 1; j < i; j++ {
            left := dp[j]
            right := dp[i-j]
            prod := left.value * right.value
            cuts := left.cuts + right.cuts + 1
​
            if prod > maxVal || (prod == maxVal && cuts < minCuts) {
                maxVal = prod
                minCuts = cuts
                cutPos = j
            }
        }
​
        dp[i] = State{maxVal, minCuts}
        path[i] = cutPos
    }
​
    var res []int
    backtrack(X, path, &res)
    sort.Ints(res)
​
    for i, v := range res {
        fmt.Print(v)
        if i != len(res)-1 {
            fmt.Print(" ")
        }
    }
    fmt.Println()
}
